+@code {
+    private List<TaskItem> allTasks = new();
+    private string searchTerm = string.Empty;
+    private bool isLoading = true;
+    private string? errorMessage;
+
+    private static readonly string[] Columns = { "To Do", "In Progress", "Done" };
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadTasks();
+    }
+
+    private async Task LoadTasks()
+    {
+        try
+        {
+            isLoading = true;
+            errorMessage = null;
+            allTasks = await TaskService.GetAllTasksAsync();
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to load tasks: {ex.Message}";
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private List<TaskItem> GetTasksForStatus(string status)
+    {
+        var tasks = allTasks.Where(t => t.Status == status);
+        if (!string.IsNullOrWhiteSpace(searchTerm))
+        {
+            tasks = tasks.Where(t => t.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase));
+        }
+        return tasks.ToList();
+    }
+
+    private void HandleSearchChanged(string value)
+    {
+        searchTerm = value;
+    }
+
+    private async Task HandleMoveTask((int TaskId, MoveDirection Direction) args)
+    {
+        var task = allTasks.FirstOrDefault(t => t.Id == args.TaskId);
+        if (task is null) return;
+
+        var currentIndex = Array.IndexOf(Columns, task.Status);
+        var newIndex = args.Direction == MoveDirection.Left ? currentIndex - 1 : currentIndex + 1;
+
+        if (newIndex < 0 || newIndex >= Columns.Length) return;
+
+        var newStatus = Columns[newIndex];
+
+        try
+        {
+            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
+            // Update local state
+            allTasks = allTasks.Select(t => t.Id == task.Id ? t with { Status = newStatus } : t).ToList();
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to move task: {ex.Message}";
+        }
+    }
+
+    private async Task HandleAddTask((string Title, string Assignee, string Priority, DateTime DueDate) data, string status)
+    {
+        try
+        {
+            var newTask = await TaskService.CreateTaskAsync(data.Title, data.Assignee, data.Priority, data.DueDate);
+            // CreateTaskAsync returns the task; ensure it has the correct status
+            allTasks.Add(newTask with { Status = status });
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to create task: {ex.Message}";
+        }
+    }
+}
